#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-modal.sh — Installs/updates Modal CLI
# Safe to re-run — detects existing install and upgrades as needed.
#
# macOS/Linux: Uses uv (preferred) or pip/pip3. Requires Python 3.10+.
#
# Authentication (modal setup) is interactive and must be run separately
# after install — not automated by this script.
#
# See reference/tool-registry.md for install source details.

set -euo pipefail

# --- Shared library ---
# aitools-lib.sh -- shared helpers for all aitools bash scripts
# Sourced, not executed directly. No shebang, no set -euo pipefail (caller sets it).
#
# Provides: platform detection, display_path, read_config_key, logging_init,
# log/log_ok/log_error/log_warn, write_summary, show_summary.
#
# Usage:
#   source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/aitools-lib.sh"
#   logging_init "script-name"
#
# Entry points (aitools, aitools-install) override log functions after sourcing
# for specialized logging (file-only, JSONL, etc.).

# ---------------------------------------------------------------------------
# Platform detection
# ---------------------------------------------------------------------------
IS_MACOS=false
IS_WINDOWS=false
case "$(uname -s)" in
    Darwin*)              IS_MACOS=true ;;
    MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;;
esac

# ---------------------------------------------------------------------------
# Log directory (platform-aware)
# ---------------------------------------------------------------------------
AITOOLS_LOG_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/aitools"
$IS_MACOS && AITOOLS_LOG_DIR="$HOME/Library/Logs/aitools"

# ---------------------------------------------------------------------------
# Module-level counters (safe for sourcing without logging_init under set -u)
# ---------------------------------------------------------------------------
ERRORS=0
WARNINGS=0

# ---------------------------------------------------------------------------
# Display-friendly path (native Windows on MSYS, no-op elsewhere)
# ---------------------------------------------------------------------------
display_path() {
    if command -v cygpath &>/dev/null; then
        cygpath -w "$1"
    else
        printf '%s' "$1"
    fi
}

# ---------------------------------------------------------------------------
# Config reader (pure bash, handles UTF-8 BOM)
# ---------------------------------------------------------------------------
# Read a top-level string value from a JSON config file.
# Handles UTF-8 BOM (PowerShell 5.x writes one) and JSON-escaped backslashes.
read_config_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 1
    local val
    val=$(tr -d '\357\273\277' < "$file" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | cut -d'"' -f4)
    [ -n "$val" ] || return 1
    # Unescape JSON backslashes: \\ -> \
    printf '%b' "$val"
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets SCRIPT_NAME, LOG_DIR, LOG_FILE; resets ERRORS, WARNINGS; creates log dir.
# Usage: logging_init "setup-foo"
logging_init() {
    SCRIPT_NAME="${1:?logging_init requires a script name}"
    LOG_DIR="$AITOOLS_LOG_DIR"
    LOG_FILE="$LOG_DIR/deploy.log"
    mkdir -p "$LOG_DIR"
    ERRORS=0
    WARNINGS=0
}

# ---------------------------------------------------------------------------
# Standard logging (Pattern A: console + log file, with [level] tag)
# ---------------------------------------------------------------------------
log() {
    local level="${2:-info}"
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    local line="[$ts] [$SCRIPT_NAME] [$level] $1"
    printf '%s\n' "$line" >> "$LOG_FILE"
    case "$level" in
        error) printf '\033[31m%s\033[0m\n' "$line" ;;
        warn)  printf '\033[33m%s\033[0m\n' "$line" ;;
        *)     printf '%s\n' "$line" ;;
    esac
}
log_ok()    { log "$1" "ok"; }
log_error() { log "$1" "error"; ERRORS=$((ERRORS + 1)); }
log_warn()  { log "$1" "warn"; WARNINGS=$((WARNINGS + 1)); }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
write_summary() {
    if [ -n "${AITOOLS_SUMMARY_FILE:-}" ]; then
        printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$AITOOLS_SUMMARY_FILE"
    fi
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
show_summary() {
    local sfile="${AITOOLS_SUMMARY_FILE:-}"
    [ -n "$sfile" ] || return 0
    [ -f "$sfile" ] || return 0
    [ -s "$sfile" ] || { rm -f "$sfile"; return 0; }
    echo ""
    echo "────────────────────────────────────────────────────────"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "OK"   ] && printf '\033[32m  [ok]  %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "WARN" ] && printf '\033[33m  [!]   %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "ERROR" ] && printf '\033[31m  [ERR] %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    local first_action=true
    while IFS='|' read -r cat tool detail; do
        if [ "$cat" = "ACTION" ]; then
            if [ "$first_action" = true ]; then
                echo ""
                printf '\033[1;35m  ACTION REQUIRED -- run before tools are ready:\033[0m\n'
                first_action=false
            fi
            printf '\033[1;35m  >>  %s\033[0m\n' "$detail"
        fi
    done < "$sfile"
    echo "────────────────────────────────────────────────────────"
    rm -f "$sfile"
}
logging_init "setup-modal"

# --- OS guard ---
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
        log_error "This script is for macOS/Linux. On Windows, use ${SCRIPT_NAME}.ps1 instead."
        exit 1 ;;
esac

# Refresh PATH hash to pick up tools installed by prior steps (e.g., setup-python, setup-uv)
hash -r

# --- Python package installer check (uv-first) ---
INSTALL_CMD=""
INSTALL_FLAGS=""
INSTALL_LABEL=""
if command -v uv >/dev/null 2>&1; then
    INSTALL_CMD="uv pip"
    INSTALL_FLAGS="--system"
    INSTALL_LABEL="uv"
    log "Using uv for package install"
elif command -v pip3 >/dev/null 2>&1; then
    INSTALL_CMD="pip3"
    INSTALL_LABEL="pip3"
    log "Using pip3 for package install (uv not found)"
elif command -v pip >/dev/null 2>&1; then
    INSTALL_CMD="pip"
    INSTALL_LABEL="pip"
    log "Using pip for package install (uv not found)"
else
    log_error "No Python package installer found. Install uv or pip first."
    write_summary ERROR "modal cli" "no package installer (uv/pip) found"
    exit 1
fi

# Verify Python 3.10+
PYTHON_CMD=""
if command -v python3 >/dev/null 2>&1; then
    PYTHON_CMD="python3"
elif command -v python >/dev/null 2>&1; then
    PYTHON_CMD="python"
fi

if [ -n "$PYTHON_CMD" ]; then
    PY_VERSION=$("$PYTHON_CMD" -c "import sys; print(str(sys.version_info.major) + '.' + str(sys.version_info.minor))" 2>/dev/null)
    PY_MAJOR=$(printf '%s' "$PY_VERSION" | cut -d. -f1)
    PY_MINOR=$(printf '%s' "$PY_VERSION" | cut -d. -f2)
    if [ "$PY_MAJOR" -lt 3 ] || { [ "$PY_MAJOR" -eq 3 ] && [ "$PY_MINOR" -lt 10 ]; }; then
        log_error "Python 3.10+ required. Found Python $PY_VERSION"
        write_summary ERROR "modal cli" "Python 3.10+ required (found $PY_VERSION)"
        exit 1
    fi
    log "Python $PY_VERSION found ($PYTHON_CMD)"
fi

# --- Install/update ---
if command -v modal >/dev/null 2>&1; then
    MODAL_VERSION=$(modal --version 2>/dev/null || echo "version unknown")
    log "Modal CLI already installed ($MODAL_VERSION)"
    log "Upgrading via $INSTALL_LABEL..."
    PIP_OUTPUT=$($INSTALL_CMD install $INSTALL_FLAGS --upgrade modal 2>&1) || true
    printf '%s\n' "$PIP_OUTPUT" | while IFS= read -r line; do log "$line"; done
    pip_notice=$(printf '%s\n' "$PIP_OUTPUT" | grep -o '\[notice\] A new release of pip is available: .*' | head -1 || true)
    if [ -n "$pip_notice" ]; then
        pip_versions="${pip_notice#*: }"
        log_warn "pip upgrade available: $pip_versions"
        write_summary WARN "pip" "upgrade available: $pip_versions"
    fi
    if printf '%s\n' "$PIP_OUTPUT" | grep -qi '^ERROR:'; then
        log_error "pip reported errors during upgrade (see log above)"
        write_summary ERROR "modal cli" "pip dependency conflict (see log)"
    fi
    if command -v modal >/dev/null 2>&1; then
        MODAL_VERSION=$(modal --version 2>/dev/null || echo "version unknown")
        log_ok "Modal CLI upgraded ($MODAL_VERSION)"
        write_summary OK "modal cli" "$MODAL_VERSION"
    else
        log_error "$INSTALL_LABEL upgrade completed but 'modal' not found in PATH"
        write_summary ERROR "modal cli" "upgrade succeeded but not on PATH"
    fi
else
    log "Installing Modal CLI via $INSTALL_LABEL..."
    PIP_OUTPUT=$($INSTALL_CMD install $INSTALL_FLAGS modal 2>&1) || true
    printf '%s\n' "$PIP_OUTPUT" | while IFS= read -r line; do log "$line"; done
    pip_notice=$(printf '%s\n' "$PIP_OUTPUT" | grep -o '\[notice\] A new release of pip is available: .*' | head -1 || true)
    if [ -n "$pip_notice" ]; then
        pip_versions="${pip_notice#*: }"
        log_warn "pip upgrade available: $pip_versions"
        write_summary WARN "pip" "upgrade available: $pip_versions"
    fi
    if printf '%s\n' "$PIP_OUTPUT" | grep -qi '^ERROR:'; then
        log_error "pip reported errors during install (see log above)"
        write_summary ERROR "modal cli" "pip dependency conflict (see log)"
    fi
    if command -v modal >/dev/null 2>&1; then
        MODAL_VERSION=$(modal --version 2>/dev/null || echo "version unknown")
        log_ok "Modal CLI installed ($MODAL_VERSION)"
        log_ok "Install path: $(command -v modal)"
        write_summary OK "modal cli" "$MODAL_VERSION"
    else
        log_error "Modal installed but 'modal' not found in PATH"
        write_summary ERROR "modal cli" "installed but not on PATH"
        log_warn "You may need to add Python's bin directory to PATH."
        if [ -n "$PYTHON_CMD" ]; then
            log_warn "Try: $PYTHON_CMD -m modal --version"
        fi
    fi
fi

# --- pip dependency check (only when using pip, not uv) ---
if [ "$INSTALL_LABEL" != "uv" ]; then
PIP_CHECK_CMD="$INSTALL_CMD"
pip_check_output=$($PIP_CHECK_CMD check 2>&1) || true
if [ -n "$pip_check_output" ]; then
    printf '%s\n' "$pip_check_output" | while IFS= read -r line; do
        [ -n "$line" ] && log_warn "pip conflict: $line"
    done
    write_summary WARN "pip" "dependency conflicts found (see log)"
fi
fi

log_warn "Authentication required: run 'modal setup' to authenticate (browser flow)"
write_summary ACTION "" "modal setup -- authenticate modal (browser flow)"

# --- Exit ---
if [ "$ERRORS" -gt 0 ]; then
    log "FAILED with $ERRORS error(s)" "error"
    exit 1
elif [ "$WARNINGS" -gt 0 ]; then
    log "COMPLETED with $WARNINGS warning(s)" "warn"
    exit 0
else
    log "COMPLETED successfully" "ok"
    exit 0
fi
